import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long next() {
        while (buf[pos] != '-' && (buf[pos] < '0' || buf[pos] > '9')) pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long x = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') x = x * 10 + (buf[pos++] - '0');
        return neg ? -x : x;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) next();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = (int) next();
        // Value v belongs at index n-v; a cycle of length L needs L-1 swaps.
        boolean[] seen = new boolean[n];
        long answer = 0;
        for (int start = 0; start < n; start++) {
            if (seen[start]) continue;
            int v = start, length = 0;
            while (!seen[v]) {
                seen[v] = true;
                length++;
                v = n - a[v];
            }
            answer += length - 1;
        }
