package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func next() int64 {
	for data[pos] != '-' && (data[pos] < '0' || data[pos] > '9') {
		pos++
	}
	neg := data[pos] == '-'
	if neg {
		pos++
	}
	var x int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		x = x*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -x
	}
	return x
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(next())
	a := make([]int, n)
	for i := range a {
		a[i] = int(next())
	}
	// Value v belongs at index n-v; a cycle of length L needs L-1 swaps.
	seen := make([]bool, n)
	answer := 0
	for start := 0; start < n; start++ {
		if seen[start] {
			continue
		}
		v, length := start, 0
		for !seen[v] {
			seen[v] = true
			length++
			v = n - a[v]
		}
		answer += length - 1
	}
	fmt.Println(answer)
}
